/**
 * Paths the change journal does not track.
 *
 * The journal answers "what did this run do to the workspace". Two kinds of
 * path are not that:
 *
 *   - a file under `/tmp` or the OS temp directory — scratch, often written by
 *     a test runner or a throwaway script, and a recursive scan of a temp root
 *     is unbounded noise;
 *   - a file under a build/output directory (`dist`, `build`, `node_modules`,
 *     `target`, …) — generated by a build, not edited by the agent. A `bun run
 *     build` in a run otherwise adds every emitted chunk to that run's list.
 *
 * Both the writer and the reader drop these paths, so an old journal that
 * recorded one does not show it either. The temp roots are resolved through
 * `realpathSync` because macOS exposes `/tmp` as a symlink to `/private/tmp`
 * and `os.tmpdir()` under `/var/folders`, and a tool may spell the same file
 * either way.
 */

import { realpathSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const EXCLUDED_ROOTS: readonly string[] = (() => {
  const roots = new Set<string>();
  for (const candidate of ['/tmp', os.tmpdir()]) {
    roots.add(path.resolve(candidate));
    try {
      roots.add(realpathSync(candidate));
    } catch {
      // A temp root that does not exist is simply not excluded.
    }
  }
  return [...roots];
})();

/** True when `absolute` is `/tmp`, the OS temp dir, or anything below them. */
export function isTempPath(absolute: string): boolean {
  const resolved = path.resolve(absolute);
  return EXCLUDED_ROOTS.some((root) => resolved === root || resolved.startsWith(root + path.sep));
}

/** Directory names whose contents are generated, not edited. */
const BUILD_DIRS: Record<string, true> = {
  dist: true, build: true, out: true, coverage: true, node_modules: true,
  '.next': true, '.nuxt': true, '.svelte-kit': true, '.turbo': true,
  '.cache': true, '.output': true, target: true, obj: true, release: true,
  'test-results': true, 'playwright-report': true, Pods: true,
  DerivedData: true, vendor: true,
};

/** True when `absolute` is inside a build/output directory under `cwd`. */
export function isBuildPath(absolute: string, cwd: string): boolean {
  const check = (base: string): boolean => {
    const relative = path.relative(base, absolute);
    if (!relative || relative.startsWith('..') || path.isAbsolute(relative)) return false;
    return relative.split(path.sep).some((segment) => BUILD_DIRS[segment] === true);
  };
  if (check(cwd)) return true;
  try {
    return check(realpathSync(cwd));
  } catch {
    return false;
  }
}

/**
 * True when `absolute` is `root` or below it.
 *
 * The realpath fallback matters because a git root is a realpath while the
 * caller's cwd may be a symlinked spelling (`/var/folders` vs
 * `/private/var/folders` on macOS). The parent directory is resolved rather
 * than the file, so a deleted file still compares.
 */
export function isInside(absolute: string, root: string): boolean {
  const resolved = path.resolve(absolute);
  const base = path.resolve(root);
  if (resolved === base || resolved.startsWith(base + path.sep)) return true;
  try {
    const realAbsolute = path.join(realpathSync(path.dirname(absolute)), path.basename(absolute));
    const realBase = realpathSync(root);
    return realAbsolute === realBase || realAbsolute.startsWith(realBase + path.sep);
  } catch {
    return false;
  }
}

/**
 * The journal's rule: a temp path is scratch only when it is OUTSIDE the
 * session cwd. A workspace that itself lives under `/tmp` (a test checkout)
 * keeps its files; a command that writes `/tmp/other` from a real workspace
 * does not.
 */
export function isExcludedTempPath(absolute: string, cwd: string): boolean {
  return isTempPath(absolute) && !isInside(absolute, cwd);
}
